# ----------------- Fill policy: how to treat missing answers -----------------
# Options:
#   "null"  -> keep None (current behavior)
#   "blank" -> use empty string u""
#   "dash"  -> use em dash u"—"
#   "prev"  -> forward-fill from previous column (last non-null)
FILL_POLICY = "blank"

def _apply_fill_policy(current_value, row_idx, col_idx, dsIn):
    """current_value may be None if absent; apply chosen policy."""
    if current_value is not None:
        return current_value
    if FILL_POLICY == "null":
        return None
    if FILL_POLICY == "blank":
        return u""
    if FILL_POLICY == "dash":
        return u"—"
    if FILL_POLICY == "prev":
        # Forward-fill: look left to right (older columns are to the right after your rebuild),
        # so scan prior columns for the same row.
        # Columns are: ["Description", <newCol>, ...rest...]
        # We consider only answer columns (skip Description/ID).
        cols = dsIn.getColumnCount()
        names = [dsIn.getColumnName(i) for i in range(cols)]
        for c in range(0, cols):
            name = names[c]
            if name in ("Description", "ID"):
                continue
            try:
                v = dsIn.getValueAt(row_idx, c)
                if v is not None and (unicode(v).strip() != u""):
                    return v
            except:
                pass
        return None  # nothing to carry forward
    # default
    return None

